css:
/* Main Receipt */

.receipt {
    width: 90%;
    max-width: 800px;
    margin: 30px auto;
    padding: 35px;
    font-family: Arial, Helvetica, sans-serif;
    font-size: 13px;
    color: #222;
    background: #ffffff;
    border: 1px solid #d9d9d9;
    box-sizing: border-box;
}


/* Header */

.receipt-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
}

.receipt-header h1 {
    margin: 0;
    font-size: 28px;
    letter-spacing: 1px;
}

.receipt-header p {
    margin: 6px 0 0;
    font-size: 13px;
    color: #777;
}


/* Status */

.receipt-status {
    padding: 8px 16px;
    border: 1px solid #333;
    font-size: 12px;
    font-weight: bold;
    text-transform: uppercase;
}


/* Divider */

.divider {
    border-top: 2px solid #333;
    margin: 15px 0 25px;
}


/* Receipt Information */

.receipt-info {
    display: flex;
    justify-content: space-between;
    margin-bottom: 25px;
}

.receipt-info > div {
    width: 48%;
}

.label {
    display: block;
    margin-bottom: 5px;
    font-size: 11px;
    color: #777;
    text-transform: uppercase;
}

.value {
    font-weight: bold;
}


/* Section Headings */

.receipt h2 {
    margin: 25px 0 10px;
    padding-bottom: 7px;
    font-size: 16px;
    border-bottom: 1px solid #ccc;
}


/* Tables */

.receipt table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 20px;
}

.receipt td {
    padding: 10px;
    border: 1px solid #ddd;
    vertical-align: middle;
}

.field-label {
    width: 35%;
    font-weight: bold;
}


/* Amount Paid */

.amount-row td {
    font-size: 15px;
    font-weight: bold;
}


/* Confirmation */

.confirmation {
    margin-top: 25px;
    padding: 18px;
    text-align: center;
    border: 1px solid #ccc;
}

.confirmation strong {
    font-size: 15px;
}

.confirmation p {
    margin: 7px 0 0;
    font-size: 12px;
    color: #666;
}


/* Footer */

.receipt-footer {
    margin-top: 30px;
    padding-top: 15px;
    text-align: center;
    border-top: 1px solid #ddd;
    color: #777;
    font-size: 11px;
}

.receipt-footer p {
    margin: 4px 0;
}


/* PDF Printing */

@media print {
    .receipt {
        width: 100%;
        margin: 0;
        border: none;
        padding: 20px;
    }
}
